import{_ as l,l as i,o as e,c as n,v as r,p as s,x as t,d as C,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"CYK 与 CFL 判定","description":"","frontmatter":{"title":"CYK 与 CFL 判定","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cyk-parsing.md","filePath":"cs/cyk-parsing.md","lastUpdated":1789023840000}'),d={name:"cs/cyk-parsing.md"};function h(m,a,_,F,f,u){const o=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="cyk-与-cfl-判定" tabindex="-1">CYK 与 CFL 判定 <a class="header-anchor" href="#cyk-与-cfl-判定" aria-label="Permalink to &quot;CYK 与 CFL 判定&quot;">​</a></h1><div class="epigraph"><p>Chomsky 范式下，子串是否由某非终结符推出，可用动态规划在立方时间填表；一般 CFL 的成员问题因此可判定。</p><footer>—— 据 Cocke；Kasami, 1965；Younger, 1967；Hopcroft and Ullman 整理</footer></div><p>上一课<a href="/cs/pumping-lemma-cfl">CFL 泵引理</a>只会排除，不会接收。主干<a href="/cs/cfg-grammar">CFG</a>把分析算法留给「受限族」，并点名 CYK。缺口是：对<strong>任意</strong> CFG（先化成 CNF），成员问题 \\(w\\in L(G)\\) 可判定，复杂度 \\(O(n^3|G|)\\)，不是词法那条线性 DFA。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PDA 非确定，直接模拟可能指数分叉。CNF：产生式仅 \\(A\\to BC\\) 或 \\(A\\to a\\)。令 \\(V_{i,\\ell}\\) 为能推出子串 \\(w_i\\cdots w_{i+\\ell-1}\\) 的非终结符集合。长度 1 查终结产生式；长度 \\(\\ell\\) 枚举切点，\\(A\\to BC\\) 当 \\(B\\) 认左段、\\(C\\) 认右段。\\(S\\in V_{1,n}\\) 当且仅当接受。</p><p>这是判定，顺便可得一棵（或所有）推导树。编程语言不用 CYK 当主分析器：立方太慢，且要 CNF；LL/LR 线性。本课要的是<strong>一般 CFL 可判定</strong>，对照后课图灵机的停机。</p><h3 id="cnf-不是「唯一树」" tabindex="-1">CNF 不是「唯一树」 <a class="header-anchor" href="#cnf-不是「唯一树」" aria-label="Permalink to &quot;CNF 不是「唯一树」&quot;">​</a></h3><p>化 CNF 改写树的形状，语言不变。\\(\\varepsilon\\) 与单位产生式要先消去（空串单独处理）。二义文法会在表里留下多条组合，CYK 不负责消二义。</p><p><span class="marginnote">独立发现：Cocke、Kasami 1965、Younger 1967。龙书把它当一般 CFG 的 DP。Earley 算法覆盖更广的文法形状，本课不展开。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>给定 \\(G\\) 与 \\(w\\)，先化 CNF，再填三角表。构造性：从 \\(S\\) 回溯切点可建树。复杂度：每个格子 \\(O(\\ell\\cdot |P|)\\)，总 \\(O(n^3|G|)\\)。空语言、有限性对 CFL 也可判定；等价性不可判定——点名，不证。</p>',11)),(e(),s(p,null,{default:t(()=>[c(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CFG%5B%22CFG%22%5D%20--%3E%20CNF%5B%22Chomsky%20%E8%8C%83%E5%BC%8F%22%5D%0A%20%20CNF%20--%3E%20DP%5B%22CYK%20%E5%A1%AB%E8%A1%A8%22%5D%0A%20%20DP%20--%3E%20MEM%5B%22w%20%E6%98%AF%E5%90%A6%E5%9C%A8%20L(G)%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[C(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>主干<a href="/cs/interval-dp">区间 DP</a> 已见按长度填区间；CYK 是同一张表，格子里是非终结符集合而非数值。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>可判定不等于高效，更不等于确定栈。CFL 的补不可判定是否 CFL，但给定固定 \\(G\\)，对每个 \\(w\\) 仍可回答成员——\\(G\\) 是算法的一部分。换一台机器认「任意 CFG 的任意 \\(w\\)」是另一问题（通用性），后课图灵机才需要。</p><p>DPDA / LR 把非确定压掉，换来线性；不是所有 CFG 都能这样。</p><p>表 \\(V_{i,\\ell}\\) 与区间 DP 同形，格子里是非终结符集合而非最优值。回溯切点可得一棵树；二义时多棵。CFL 空性：化 CNF 后看 \\(S\\) 能否推出任何终结串，也可判定。等价、固有二义不可判定，本课点名，避免把「可判定」理解成「文法的一切性质」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 CFL 等价不可判定，不写 Earley。不把 CYK 当自然语言语法的充分模型。后课默认：CFL 成员可判定、多项式；下一层机器将越过可判定边界。图灵机是下一课。</p><p>固定文法的成员可判定，不等于文法等价可判定。编译前端仍走 LL/LR，是因为立方与 CNF 改写都不适合源级分析。图灵机将越过这层「总有算法」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CNF + 区间 DP：一般 CFL 成员 \\(O(n^3)\\) 可判定。</li><li>编译前端仍用 LL/LR；CYK 给理论闭合。</li><li>判定固定文法的成员，不是判定两文法是否等价。</li><li>出处：Kasami, 1965；Younger, 1967；Hopcroft and Ullman。</li></ul>',10))])}const P=l(d,[["render",h]]);export{A as __pageData,P as default};
